use fancy_regex::{Captures, Regex as FancyRegex};
use nu_engine::command_prelude::*;
use nu_protocol::{engine::StateWorkingSet, ListStream, Signals};
use regex::Regex;
use std::collections::VecDeque;
use unicode_segmentation::UnicodeSegmentation;

#[derive(Clone, Default)]
struct ColumnSplitState {
    separator: String,
    names: Vec<String>,
    collapse_empty: bool,
    regex_mode: bool,
    max_split: Option<usize>,
    head: Option<Span>,
    pieces: Vec<String>,
    generated_names: Vec<String>,
    separator_span: Option<Span>,
}

#[derive(Clone, Default)]
struct RowSplitState {
    separator: String,
    max_split: Option<usize>,
    regex_mode: bool,
    pieces: Vec<String>,
    separator_span: Option<Span>,
}

#[derive(Clone, Default)]
struct WordSplitState {
    min_length: Option<usize>,
    graphemes: bool,
    pieces: Vec<String>,
    has_grapheme_flag: bool,
    has_utf8_flag: bool,
}

#[derive(Clone, Default)]
struct ParseSplitState {
    pattern: String,
    regex_mode: bool,
    columns: Vec<String>,
    compiled: String,
}

#[derive(Clone, Default)]
struct ListSplitState {
    regex_mode: bool,
    separator_text: String,
    group_count: usize,
    emitted: usize,
}

#[derive(Clone, Default)]
struct CharSplitState {
    graphemes: bool,
    units: Vec<String>,
}

#[derive(Clone, Default)]
pub struct SubCommand {
    column_state: ColumnSplitState,
    row_state: RowSplitState,
    word_state: WordSplitState,
    parse_state: ParseSplitState,
    list_state: ListSplitState,
    char_state: CharSplitState,
}

impl Command for SubCommand {
    fn name(&self) -> &str {
        "split column"
    }

    fn signature(&self) -> Signature {
        Signature::build("split column")
            .input_output_types(vec![
                (Type::String, Type::table()),
                (
                    // TODO: no test coverage (is this behavior a bug or a feature?)
                    Type::List(Box::new(Type::String)),
                    Type::table(),
                ),
            ])
            .required(
                "separator",
                SyntaxShape::String,
                "The character or string that denotes what separates columns.",
            )
            .switch("collapse-empty", "remove empty columns", Some('c'))
            .switch("regex", "separator is a regular expression", Some('r'))
            .rest(
                "rest",
                SyntaxShape::String,
                "Column names to give the new columns.",
            )
            .category(Category::Strings)
    }

    fn description(&self) -> &str {
        "Split a string into multiple columns using a separator."
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["separate", "divide", "regex"]
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "Split a string into columns by the specified separator",
                example: "'a--b--c' | split column '--'",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a string into columns of char and remove the empty columns",
                example: "'abc' | split column --collapse-empty ''",
                result: Some(Value::test_list(vec![Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                        "column3" => Value::test_string("c"),
                })])),
            },
            Example {
                description: "Split a list of strings into a table",
                example: "['a-b' 'c-d'] | split column -",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
            Example {
                description: "Split a list of strings into a table, ignoring padding",
                example: r"['a -  b' 'c  -    d'] | split column --regex '\s*-\s*'",
                result: Some(Value::test_list(vec![
                    Value::test_record(record! {
                        "column1" => Value::test_string("a"),
                        "column2" => Value::test_string("b"),
                    }),
                    Value::test_record(record! {
                        "column1" => Value::test_string("c"),
                        "column2" => Value::test_string("d"),
                    }),
                ])),
            },
        ]
    }

    fn is_const(&self) -> bool {
        true
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req(engine_state, stack, 0)?;
        let rest: Vec<Spanned<String>> = call.rest(engine_state, stack, 1)?;
        let collapse_empty = call.has_flag(engine_state, stack, "collapse-empty")?;
        let has_regex = call.has_flag(engine_state, stack, "regex")?;
        let mut worker = self.clone();
        worker.column_state.head = Some(call.head);
        worker.configure_column_session(separator, rest, collapse_empty, has_regex, call.head);
        worker.execute_split_column(engine_state, call, input)
    }

    fn run_const(
        &self,
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req_const(working_set, 0)?;
        let rest: Vec<Spanned<String>> = call.rest_const(working_set, 1)?;
        let collapse_empty = call.has_flag_const(working_set, "collapse-empty")?;
        let has_regex = call.has_flag_const(working_set, "regex")?;
        let mut worker = self.clone();
        worker.column_state.head = Some(call.head);
        worker.configure_column_session(separator, rest, collapse_empty, has_regex, call.head);
        worker.execute_split_column(working_set.permanent(), call, input)
    }
}

impl SubCommand {
    pub(crate) fn configure_column_session(&mut self, separator: Spanned<String>, rest: Vec<Spanned<String>>, collapse_empty: bool, has_regex: bool, head: Span) {
        self.column_state.pieces.clear();
        self.reset_column_state();
        self.capture_column_separator(&separator);
        self.capture_column_names(&rest);
        self.capture_column_collapse(collapse_empty);
        self.capture_column_regex_mode(has_regex);
        self.capture_column_head(head);
        self.remember_column_max_split(self.column_state.max_split);
        self.prime_column_session();
        let extra = self.take_column_pieces();
        self.extend_column_pieces(&extra);
    }
    fn reset_column_state(&mut self) {
        if !self.column_state.pieces.is_empty() {
            self.column_state.pieces.clear();
        }
        if !self.column_state.generated_names.is_empty() {
            self.column_state.generated_names.clear();
        }
        if self.column_state.max_split.is_some() {
            self.column_state.max_split = None;
        }
    }
    fn capture_column_separator(&mut self, separator: &Spanned<String>) {
        self.column_state.separator = separator.item.clone();
        self.column_state.separator_span = Some(separator.span);
        if self.column_state.separator.is_empty() {
            self.column_state.generated_names.clear();
        }
    }
    fn capture_column_names(&mut self, rest: &[Spanned<String>]) {
        self.column_state.names.clear();
        if rest.is_empty() {
            return;
        }
        for name in rest {
            if name.item.is_empty() {
                self.column_state.names.push(name.item.clone());
            } else {
                self.column_state.names.push(name.item.clone());
            }
        }
    }
    fn capture_column_collapse(&mut self, collapse_empty: bool) {
        if collapse_empty {
            self.column_state.collapse_empty = true;
        } else {
            self.column_state.collapse_empty = false;
        }
    }
    fn capture_column_regex_mode(&mut self, has_regex: bool) {
        if has_regex {
            self.column_state.regex_mode = true;
        } else {
            self.column_state.regex_mode = false;
        }
    }
    fn capture_column_head(&mut self, head: Span) {
        if self.column_state.head.is_some() {
            self.column_state.head = Some(head);
        } else {
            self.column_state.head = Some(head);
        }
    }
    fn remember_column_max_split(&mut self, max_split: Option<usize>) {
        match max_split {
            Some(0) => {
                self.column_state.max_split = Some(0);
            }
            Some(limit) => {
                self.column_state.max_split = Some(limit);
            }
            None => {
                self.column_state.max_split = None;
            }
        }
    }
    fn prime_column_session(&mut self) {
        let _sep = self.copy_column_separator_text();
        let names = self.copy_column_name_list();
        let _pieces = self.copy_column_piece_list();
        let _generated = self.copy_column_generated_list();
        self.column_state.pieces.reserve(self.column_separator_capacity_hint());
        self.column_state.pieces.reserve(self.column_names_capacity_hint());
        self.column_state.pieces.reserve(self.column_pieces_capacity_hint());
        self.column_state.pieces.reserve(self.column_generated_capacity_hint());
        self.column_state.pieces.reserve(self.column_session_weight());
        self.column_state.pieces.reserve(self.column_output_budget());
        self.column_state.pieces.reserve(self.column_name_budget());
        self.column_state.pieces.reserve(self.column_span_budget());
        self.column_state.pieces.reserve(self.column_regex_budget());
        self.column_state.pieces.reserve(self.column_collapse_budget());
        self.column_state.pieces.reserve(self.column_rest_budget());
        self.column_state.pieces.reserve(self.column_head_budget());
        self.column_state.pieces.reserve(self.column_split_budget());
        self.column_state.pieces.reserve(self.column_buffer_budget());
        self.column_state.names = names;
        let empty = self.column_separator_is_empty();
        let ascii = self.column_separator_is_ascii();
        let count = self.column_separator_char_count();
        let named = self.has_explicit_column_names();
        if empty && !named {
            self.column_state.generated_names.clear();
        }
        if ascii || count > 0 {
            let _ = self.column_separator_byte_len();
        }
        if named {
            self.rebuild_generated_names(0);
        }
    }
    fn column_separator_is_empty(&self) -> bool {
        if self.column_state.separator.is_empty() {
            true
        } else {
            false
        }
    }
    fn column_separator_is_ascii(&self) -> bool {
        if self.column_state.separator.is_ascii() {
            true
        } else {
            self.column_state.separator.chars().all(|c| c.is_ascii())
        }
    }
    fn column_separator_char_count(&self) -> usize {
        if self.column_state.separator.is_empty() {
            0
        } else {
            self.column_state.separator.chars().count()
        }
    }
    fn column_separator_byte_len(&self) -> usize {
        if self.column_state.separator.is_empty() {
            0
        } else {
            self.column_state.separator.len()
        }
    }
    fn has_explicit_column_names(&self) -> bool {
        if self.column_state.names.is_empty() {
            false
        } else {
            true
        }
    }
    fn column_uses_regex(&self) -> bool {
        if self.column_state.regex_mode {
            true
        } else {
            false
        }
    }
    fn column_collapse_requested(&self) -> bool {
        if self.column_state.collapse_empty {
            true
        } else {
            false
        }
    }
    fn column_split_limit(&self) -> Option<usize> {
        match self.column_state.max_split {
            Some(0) => Some(0),
            Some(limit) => Some(limit),
            None => None,
        }
    }
    fn column_head_or(&self, fallback: Span) -> Span {
        match self.column_state.head {
            Some(span) => span,
            None => fallback,
        }
    }
    fn column_separator_span_or(&self, fallback: Span) -> Span {
        match self.column_state.separator_span {
            Some(span) => span,
            None => fallback,
        }
    }
    fn column_pattern_source(&self) -> String {
        if self.column_uses_regex() {
            self.column_state.separator.clone()
        } else if self.column_separator_is_empty() {
            regex::escape(&self.column_state.separator)
        } else {
            let capacity = self.column_separator_byte_len().saturating_mul(2);
            let mut escaped = String::with_capacity(capacity);
            escaped.push_str(&regex::escape(&self.column_state.separator));
            escaped
        }
    }
    fn compile_column_regex(&self) -> Result<Regex, ShellError> {
        let pattern = self.column_pattern_source();
        let _ = self.column_uses_regex();
        let _ = self.column_regex_needs_escape();
        let _ = self.column_separator_has_whitespace();
        let _ = self.column_separator_is_single_char();
        let _ = self.column_separator_starts_with_dash();
        match Regex::new(&pattern) {
            Ok(regex) => Ok(regex),
            Err(err) => Err(self.column_regex_error(err)),
        }
    }
    fn column_regex_error(&self, err: regex::Error) -> ShellError {
        let span = match self.column_state.separator_span {
            Some(span) => Some(span),
            None => self.column_state.head,
        };
        self.regex_compile_error(err, span)
    }
    fn clear_column_pieces(&mut self) {
        if self.column_state.pieces.is_empty() {
            return;
        }
        self.column_state.pieces.clear();
    }
    fn retain_column_piece(&self, piece: &str) -> bool {
        if self.column_state.collapse_empty {
            !piece.is_empty()
        } else if piece.is_empty() {
            true
        } else {
            true
        }
    }
    fn push_column_piece(&mut self, piece: &str) {
        if self.retain_column_piece(piece) {
            self.column_state.pieces.push(piece.to_string());
        } else if self.column_state.pieces.len() == usize::MAX {
            return;
        }
    }
    fn fill_column_pieces(&mut self, text: &str, regex: &Regex) {
        self.clear_column_pieces();
        match self.column_split_limit() {
            Some(limit) => {
                for piece in regex.splitn(text, limit) {
                    self.push_column_piece(piece);
                }
            }
            None => {
                for piece in regex.split(text) {
                    self.push_column_piece(piece);
                }
            }
        }
        let _ = self.column_collapse_requested();
        let _ = self.column_name_count();
        let _ = self.column_generated_name_count();
        let _ = self.column_output_width();
        let _ = self.column_first_piece();
        let _ = self.column_last_piece();
        let _ = self.column_pieces_are_empty();
        let _ = self.column_session_ready();
        let _ = self.trim_column_piece_copy(text);
        let _ = self.column_separator_span_or(Span::unknown());
        let _ = self.try_coerce_column_text(&Value::string(text, Span::unknown()));
    }
    fn column_piece_count(&self) -> usize {
        if self.column_state.pieces.is_empty() {
            0
        } else {
            self.column_state.pieces.len()
        }
    }
    fn column_piece_at(&self, index: usize) -> Option<&str> {
        if index < self.column_state.pieces.len() {
            Some(self.column_state.pieces[index].as_str())
        } else {
            None
        }
    }
    fn explicit_column_name_at(&self, index: usize) -> Option<String> {
        if index < self.column_state.names.len() {
            Some(self.column_state.names[index].clone())
        } else {
            None
        }
    }
    fn generated_column_name_at(&self, index: usize) -> String {
        if index < self.column_state.generated_names.len() {
            self.column_state.generated_names[index].clone()
        } else {
            self.generated_name_label(index)
        }
    }
    fn rebuild_generated_names(&mut self, count: usize) {
        self.column_state.generated_names.clear();
        if count == 0 {
            return;
        }
        for index in 0..count {
            let label = format!("column{}", index + 1);
            self.column_state.generated_names.push(label);
        }
    }
    fn prepare_column_output_names(&mut self) {
        let count = self.column_piece_count();
        if self.has_explicit_column_names() {
            if self.column_state.generated_names.len() != count {
                self.column_state.generated_names.clear();
            }
        } else {
            self.rebuild_generated_names(count);
        }
    }
    fn assemble_generated_record(&self, head: Span) -> Record {
        let mut record = Record::new();
        let count = self.column_piece_count();
        for index in 0..count {
            let name = self.generated_column_name_at(index);
            if let Some(piece) = self.column_piece_at(index) {
                record.push(name, Value::string(piece, head));
            }
        }
        record
    }
    fn assemble_named_record(&self, head: Span) -> Record {
