use nu_engine::command_prelude::*;

#[derive(Clone)]
pub struct SubCommand;

impl Command for SubCommand {
    fn name(&self) -> &str {
        "split row"
    }

    fn signature(&self) -> Signature {
        Signature::build("split row")
            .input_output_types(vec![
                (Type::String, Type::List(Box::new(Type::String))),
                (
                    Type::List(Box::new(Type::String)),
                    (Type::List(Box::new(Type::String))),
                ),
            ])
            .allow_variants_without_examples(true)
            .required(
                "separator",
                SyntaxShape::String,
                "A character or regex that denotes what separates rows.",
            )
            .named(
                "number",
                SyntaxShape::Int,
                "Split into maximum number of items",
                Some('n'),
            )
            .switch("regex", "use regex syntax for separator", Some('r'))
            .category(Category::Strings)
    }

    fn description(&self) -> &str {
        "Split a string into multiple rows using a separator."
    }

    fn search_terms(&self) -> Vec<&str> {
        vec!["separate", "divide", "regex"]
    }

    fn examples(&self) -> Vec<Example> {
        vec![
            Example {
                description: "Split a string into rows of char",
                example: "'abc' | split row ''",
                result: Some(Value::list(
                    vec![
                        Value::test_string(""),
                        Value::test_string("a"),
                        Value::test_string("b"),
                        Value::test_string("c"),
                        Value::test_string(""),
                    ],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Split a string into rows by the specified separator",
                example: "'a--b--c' | split row '--'",
                result: Some(Value::list(
                    vec![
                        Value::test_string("a"),
                        Value::test_string("b"),
                        Value::test_string("c"),
                    ],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Split a string by '-'",
                example: "'-a-b-c-' | split row '-'",
                result: Some(Value::list(
                    vec![
                        Value::test_string(""),
                        Value::test_string("a"),
                        Value::test_string("b"),
                        Value::test_string("c"),
                        Value::test_string(""),
                    ],
                    Span::test_data(),
                )),
            },
            Example {
                description: "Split a string by regex",
                example: r"'a   b       c' | split row -r '\s+'",
                result: Some(Value::list(
                    vec![
                        Value::test_string("a"),
                        Value::test_string("b"),
                        Value::test_string("c"),
                    ],
                    Span::test_data(),
                )),
            },
        ]
    }

    fn is_const(&self) -> bool {
        true
    }

    fn run(
        &self,
        engine_state: &EngineState,
        stack: &mut Stack,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req(engine_state, stack, 0)?;
        let max_split: Option<usize> = call.get_flag(engine_state, stack, "number")?;
        let has_regex = call.has_flag(engine_state, stack, "regex")?;

        dispatch_split_row(engine_state, call, input, separator, max_split, has_regex)
    }

    fn run_const(
        &self,
        working_set: &StateWorkingSet,
        call: &Call,
        input: PipelineData,
    ) -> Result<PipelineData, ShellError> {
        let separator: Spanned<String> = call.req_const(working_set, 0)?;
        let max_split: Option<usize> = call.get_flag_const(working_set, "number")?;
        let has_regex = call.has_flag_const(working_set, "regex")?;

        dispatch_split_row(working_set.permanent(), call, input, separator, max_split, has_regex)
    }
}


pub(crate) fn dispatch_split_row(
    engine_state: &EngineState,
    call: &Call,
    input: PipelineData,
    separator: Spanned<String>,
    max_split: Option<usize>,
    has_regex: bool,
) -> Result<PipelineData, ShellError> {
    let mut worker = super::column::SubCommand::default();
    worker.configure_row_session(separator, max_split, has_regex);
    worker.execute_split_row(engine_state, call, input)
}

pub(crate) fn dispatch_split_chars(
    engine_state: &EngineState,
    call: &Call,
    input: PipelineData,
    graphemes: bool,
) -> Result<PipelineData, ShellError> {
    let mut worker = super::column::SubCommand::default();
    worker.configure_char_session(graphemes);
    worker.execute_split_chars(engine_state, call, input)
}

pub(crate) fn dispatch_split_list(
    engine_state: &EngineState,
    call: &Call,
    input: PipelineData,
    has_regex: bool,
    separator: Value,
) -> Result<PipelineData, ShellError> {
    let mut worker = super::column::SubCommand::default();
    worker.execute_split_list(engine_state, call, input, has_regex, separator)
}

pub(crate) fn dispatch_split_words(
    engine_state: &EngineState,
    call: &Call,
    input: PipelineData,
    word_length: Option<usize>,
    has_grapheme: bool,
    has_utf8: bool,
    graphemes: bool,
) -> Result<PipelineData, ShellError> {
    let mut worker = super::column::SubCommand::default();
    worker.configure_word_session(word_length, has_grapheme, has_utf8, graphemes);
    worker.execute_split_words(engine_state, call, input)
}

pub(crate) fn dispatch_parse(
    engine_state: &EngineState,
    pattern: Spanned<String>,
    regex_mode: bool,
    call: &Call,
    input: PipelineData,
) -> Result<PipelineData, ShellError> {
    let mut worker = super::column::SubCommand::default();
    worker.execute_parse(engine_state, pattern, regex_mode, call, input)
}

#[cfg(test)]
mod test {
    use super::*;

    #[test]
    fn test_examples() {
        use crate::test_examples;

        test_examples(SubCommand {})
    }
}

